// oxlint-disable eslint/no-eval -- `callFromForgedNodeFrame` below exists to pin that an
// `eval` frame naming itself `node:internal/…` buys nothing; the eval IS the thing under test.
//
// Test fixture for issue #119: telling a read this package MADE from a read NODE made while
// this package's frame happened to be the nearest one with a name.
//
// Lives under a committed node_modules/ so capwall attributes its calls to
// "fixture-nodeorigin".
"use strict";
const path = require("node:path");

/** A read this package really makes, from its own frame. Must stay in the trace. */
exports.readEnv = (key) => process.env[key];

/**
 * A read NODE makes. Requiring a file that carries a `//# sourceMappingURL=` sends Node's
 * `node:internal/source_map/source_map_cache` through `process.env.NODE_V8_COVERAGE` while it
 * decides whether to cache the map — on a stack whose nearest *package* frame is this one, so
 * pre-#119 capwall charged this package with a variable it never mentions. This is the exact
 * shape that put `NODE_V8_COVERAGE` on `type-is`, `body-parser` and `router` in a stock express
 * tree.
 *
 * The require cache is cleared first because the read happens at COMPILE time; a cached module
 * is not compiled again and Node would never reach the env read.
 */
/**
 * Call `fn` from an `eval` frame that NAMES ITSELF `node:internal/…` — issue #84's forgery,
 * pointed at #119's classifier. A `//# sourceURL=` is a string this code chooses, so if it
 * could make a frame count as Node's own, any dependency could go unrecorded on demand.
 *
 * Lives in the fixture rather than in the test file because `eval` is a lint error in source,
 * and vendored fixtures are (deliberately) not linted — the odd code has to stay odd.
 */
exports.callFromForgedNodeFrame = (fn) => eval("(f) => f()\n//# sourceURL=node:internal/forged")(fn);

exports.loadSourceMapped = () => {
  const resolved = require.resolve(path.join(__dirname, "mapped.js"));
  delete require.cache[resolved];
  return require(resolved);
};
